window.HOEREN_TESTS[92] = {"id":"beim-kinderarzt","name":"Beim Kinderarzt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Kinderarztpraxis Dr. Sonne. Der Termin für die Impfung Ihres Sohnes ist diese Woche. Aber nicht am Donnerstag, sondern am Freitag um 9 Uhr. Bitte bringen Sie das Impfbuch mit. Ihr Sohn sollte gesund sein, bei Fieber bitte absagen. Bis Freitag, auf Wiederhören!","gender":"f","q":"Wann ist der Impftermin?","opts":["Am Donnerstag.","Am Freitag.","Am Montag."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Also, meine Tochter hat seit gestern Fieber und Husten mache ich mir Sorgen. Soll ich gleich zum Kinderarzt oder erst abwarten? Du hast doch auch Kinder. Was würdest du machen? Sie isst auch nicht richtig. Bitte ruf schnell zurück, ich bin unsicher. Danke!","gender":"m","q":"Was hat Markus' Tochter?","opts":["Bauchschmerzen.","Fieber und Husten.","Kopfschmerzen."],"correct":1},{"transcript":"Achtung Eltern: Bitte denken Sie an die Vorsorgeuntersuchungen für Ihre Kinder. Sie sind wichtig, um die Entwicklung zu prüfen. Wir messen Größe und Gewicht und schauen, ob alles gesund ist. Bringen Sie das gelbe Heft mit. Die Untersuchung ist kostenlos. Vereinbaren Sie rechtzeitig einen Termin!","gender":"m","q":"Was wird bei der Vorsorge gemacht?","opts":["Größe und Gewicht messen.","Nur impfen.","Blut abnehmen."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich war mit dem Baby beim Kinderarzt. Alles ist gesund, ich bin so erleichtert! Der Arzt war sehr nett und geduldig, obwohl die Kleine die ganze Zeit geweint hat. Er hat mir auch Tipps zum Schlafen gegeben. Wie geht es deinem Kleinen? Melde dich, bis bald!","gender":"f","q":"Wie war die Untersuchung beim Baby?","opts":["Es gab Probleme.","Das Baby ist krank.","Alles ist gesund."],"correct":2},{"transcript":"Liebe Eltern: Bei uns gibt es ein extra Wartezimmer für kranke Kinder, getrennt von den gesunden. So stecken sich die Kinder, die nur zur Vorsorge kommen, nicht an. Bitte sagen Sie an der Anmeldung Bescheid, warum Sie kommen. Für Spielzeug ist in beiden Zimmern gesorgt. Vielen Dank!","gender":"f","q":"Warum gibt es zwei Wartezimmer?","opts":["Damit es ruhiger ist.","Wegen des Platzes.","Damit sich gesunde Kinder nicht anstecken."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer geht warum? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das Wartezimmer ist voll mit Kindern. Hast du die Karten dabei?"},{"speaker":"Lisa","gender":"f","text":"Sie liegen in der Tasche. Fünf Termine und jedes Kind kommt aus einem anderen Grund."},{"speaker":"Lukas","gender":"m","text":"Ich bin wegen einer Impfung hier. Der Arzt gibt sie mir heute in den Arm."},{"speaker":"Lisa","gender":"f","text":"Das ist nicht leicht. Hat ein Kind starken Husten?"},{"speaker":"Lukas","gender":"m","text":"Husten hat heute kein Kind."},{"speaker":"Lisa","gender":"f","text":"Ich bin wegen Fieber hier. Seit gestern Abend ist es hoch."},{"speaker":"Lukas","gender":"m","text":"Dann bleib bitte sitzen. Tom kommt zum ersten großen Termin."},{"speaker":"Lisa","gender":"f","text":"Tom kommt zur Vorsorgeuntersuchung. Er ist drei Jahre alt und der Arzt schaut ihn ganz an."},{"speaker":"Lukas","gender":"m","text":"Das dauert etwas länger. Hat ein Kind Bauchschmerzen?"},{"speaker":"Lisa","gender":"f","text":"Bauchschmerzen hat auch kein Kind."},{"speaker":"Lukas","gender":"m","text":"Sara hat seit dem Wochenende rote Punkte."},{"speaker":"Lisa","gender":"f","text":"Sara hat einen Hautausschlag. Der ist am Rücken und ganz rot."},{"speaker":"Lukas","gender":"m","text":"Zeig das gleich dem Arzt. Tim hält sich seit der Nacht die Seite vom Kopf."},{"speaker":"Lisa","gender":"f","text":"Tim hat Ohrenschmerzen. Er hat die ganze Nacht wenig geschlafen."},{"speaker":"Lukas","gender":"m","text":"Er soll leise warten."},{"speaker":"Lisa","gender":"f","text":"Ich gebe die Karten an der Tür ab."}],"options":[{"letter":"a","text":"Fieber"},{"letter":"b","text":"Augenkontrolle"},{"letter":"c","text":"Hautausschlag"},{"letter":"d","text":"Husten"},{"letter":"e","text":"Ohrenschmerzen"},{"letter":"f","text":"Bauchschmerzen"},{"letter":"g","text":"Vorsorgeuntersuchung"},{"letter":"h","text":"Verletzung / Sturz"},{"letter":"i","text":"Impfung"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"g"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mutter","gender":"f","text":"Wie hoch ist das Fieber jetzt? 37 Grad, 40 Grad oder 39?"},{"speaker":"Ärztin","gender":"f","text":"39 Grad. Geben Sie ihm den Saft. 37 wäre normal, 40 wäre sehr hoch."},{"speaker":"Mutter","gender":"f","text":"Wie oft den Saft? Also bei 39 Grad, nicht bei 37?"},{"speaker":"Ärztin","gender":"f","text":"Bei Bedarf, höchstens dreimal am Tag. Das Fieber ist 39, nicht 37 und nicht 40."},{"speaker":"Mutter","gender":"f","text":"Verstanden, 39 Grad, Saft bei Bedarf. Danke Ihnen."}],"q":"Wie hoch ist das Fieber?","opts":["37 Grad.","39 Grad.","40 Grad."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Darf mein Sohn morgen in die Schule? Nur einen Tag zu Hause, oder eine Woche?"},{"speaker":"Arzt","gender":"m","text":"Noch nicht, er ist ansteckend. Ein Tag ist zu wenig, eine Woche oft zu lang."},{"speaker":"Vater","gender":"m","text":"Wie lange muss er zu Hause bleiben? Einen Tag, eine Woche oder zwei Tage?"},{"speaker":"Arzt","gender":"m","text":"Noch zwei Tage. Nicht einen Tag und nicht eine Woche, zwei Tage reichen."},{"speaker":"Vater","gender":"m","text":"Gut, dann zwei Tage zu Hause. Danke."}],"q":"Wie lange muss der Sohn zu Hause bleiben?","opts":["Zwei Tage.","Eine Woche.","Einen Tag."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Tut die Impfung weh? Sehr schmerzhaft, nur ein kleiner Pieks, oder gar nicht spürbar?"},{"speaker":"Ärztin","gender":"f","text":"Nur ein kleiner Pieks. Sehr schmerzhaft ist sie nicht, und ganz ohne Gefühl auch nicht."},{"speaker":"Mutter","gender":"f","text":"Und danach? Bleibt es nur ein Pieks, nicht sehr schmerzhaft?"},{"speaker":"Ärztin","gender":"f","text":"Der Arm kann etwas wehtun, das ist normal. Es ist ein kleiner Pieks, nicht sehr schmerzhaft und nicht unsichtbar."},{"speaker":"Mutter","gender":"f","text":"Okay, dann ein kleiner Pieks. Das schafft er."}],"q":"Wie ist die Impfung?","opts":["Sehr schmerzhaft.","Gar nicht spürbar.","Nur ein kleiner Pieks."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Mein Sohn isst kaum noch. Soll er viel essen, oder vor allem schlafen, oder trinken?"},{"speaker":"Arzt","gender":"m","text":"Trinkt er wenigstens? Viel essen muss er jetzt nicht, und Schlaf kommt von allein."},{"speaker":"Vater","gender":"m","text":"Ja, viel Wasser. Also ist Trinken wichtiger als Essen und Schlafen?"},{"speaker":"Arzt","gender":"m","text":"Gut, das ist das Wichtigste: dass das Kind genug trinkt. Nicht dass es viel isst, und Schlafen hilft extra."},{"speaker":"Vater","gender":"m","text":"Verstehe, vor allem trinken. Danke."}],"q":"Was ist laut dem Arzt am wichtigsten?","opts":["Dass das Kind schläft.","Dass das Kind viel isst.","Dass das Kind genug trinkt."],"correct":2},{"lines":[{"speaker":"Mutter","gender":"f","text":"Wann ist die nächste Untersuchung? In drei Monaten, in einem Monat oder in einem Jahr?"},{"speaker":"Sprechstundenhilfe","gender":"f","text":"In drei Monaten. Ein Monat ist zu früh, ein Jahr zu spät."},{"speaker":"Mutter","gender":"f","text":"Bekomme ich eine Erinnerung? Also in drei Monaten, nicht in einem Monat?"},{"speaker":"Sprechstundenhilfe","gender":"f","text":"Ja, wir schicken Ihnen eine Karte. Der Termin ist in drei Monaten, nicht in einem Monat und nicht in einem Jahr."},{"speaker":"Mutter","gender":"f","text":"Perfekt, dann warte ich auf die Karte. Danke."}],"q":"Wann ist die nächste Untersuchung?","opts":["In einem Monat.","In drei Monaten.","In einem Jahr."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Dr. Weber, einer Kinderärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Dr. Weber, was ist das Besondere daran, Kinder zu behandeln?"},{"speaker":"Weber","gender":"f","text":"Kinder können oft nicht sagen, was ihnen fehlt, gerade die ganz Kleinen. Ich muss genau beobachten und auch mit den Eltern reden. Und ich muss den Kindern die Angst nehmen. Wenn ein Kind lacht, statt zu weinen, dann habe ich schon viel gewonnen. Das ist eine besondere Kunst."},{"speaker":"Reporter","gender":"m","text":"Sind die Eltern oft zu besorgt?"},{"speaker":"Weber","gender":"f","text":"Manche schon, aber das verstehe ich gut. Lieber einmal zu oft kommen als zu spät. Ich nehme jede Sorge ernst. Oft ist es zum Glück nichts Schlimmes, und ich kann die Eltern beruhigen. Ein bisschen Fieber gehört zum Kindsein dazu, das ist meistens normal."},{"speaker":"Reporter","gender":"m","text":"Wie wichtig sind Impfungen?"},{"speaker":"Weber","gender":"f","text":"Sehr wichtig, da bin ich ganz klar. Impfungen schützen die Kinder vor gefährlichen Krankheiten, die es früher oft gab. Manche Eltern haben Angst davor, aber diese Sorge ist meist unbegründet. Ich erkläre alles in Ruhe. Eine Impfung tut kurz weh, schützt aber ein Leben lang."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie für gesunde Kinder?"},{"speaker":"Weber","gender":"f","text":"Viel Bewegung an der frischen Luft, gesundes Essen und genug Schlaf. Und weniger Bildschirm, das ist heute ein großes Thema. Kinder sitzen zu viel vor Handy und Fernseher. Sie sollten draußen spielen, klettern, toben. Das macht sie körperlich und seelisch gesund. Das ist meine wichtigste Botschaft."},{"speaker":"Reporter","gender":"m","text":"Was lieben Sie an Ihrem Beruf?"},{"speaker":"Weber","gender":"f","text":"Ich begleite Kinder vom Baby bis zum Teenager. Ich sehe sie wachsen, das ist wunderbar. Manche, die ich als Säuglinge hatte, bringen heute ihre eigenen Kinder zu mir. Diese Verbindung über Jahre ist etwas ganz Besonderes. Ich habe den schönsten Beruf, den ich mir vorstellen kann."}],"items":[{"q":"Frau Dr. Weber findet es wichtig, den Kindern die Angst zu nehmen.","correct":"ja"},{"q":"Sie ärgert sich über besorgte Eltern und nimmt ihre Sorgen nicht ernst.","correct":"nein"},{"q":"Sie hält Impfungen für sehr wichtig.","correct":"ja"},{"q":"Sie rät zu mehr Bewegung und weniger Bildschirmzeit.","correct":"ja"},{"q":"Sie findet ihren Beruf langweilig.","correct":"nein"}]}]};
